-- ── TEMPO ────────────────────────────────────────────────────────────────────
-- Tempo markings are written as text in scores, not symbols
('Larghissimo',   'Extremely slow and broad — typically below 24 beats per minute.',                                                                             'Tempo', 'Italian', NULL),
('Grave',         'Slow and solemn in character, conveying a sense of weight and seriousness.',                                                                  'Tempo', 'Italian', NULL),
('Largo',         'Very slow and broad, approximately 40–60 beats per minute. Conveys a wide, expansive feel.',                                                  'Tempo', 'Italian', NULL),
('Larghetto',     'Slow but with a slightly more flowing quality than the broadest tempos. Approximately 60–66 beats per minute.',                               'Tempo', 'Italian', NULL),
('Adagio',        'Slow and stately, approximately 60–76 beats per minute.',                                                                                     'Tempo', 'Italian', NULL),
('Adagietto',     'Unhurried but gently flowing — slightly more animated than a fully slow tempo. Approximately 70–80 beats per minute.',                        'Tempo', 'Italian', NULL),
('Andante',       'At a calm, walking pace, approximately 76–108 beats per minute. Literally "going" in Italian.',                                               'Tempo', 'Italian', NULL),
('Andantino',     'At a gentle, slightly varied walking pace. Historically interpreted differently by different composers.',                                      'Tempo', 'Italian', NULL),
('Moderato',      'At a moderate pace, approximately 108–120 beats per minute — neither fast nor slow.',                                                         'Tempo', 'Italian', NULL),
('Allegretto',    'Moderately fast and light in character, approximately 112–120 beats per minute.',                                                             'Tempo', 'Italian', NULL),
('Allegro',       'Fast and lively, approximately 120–168 beats per minute.',                                                                                    'Tempo', 'Italian', NULL),
('Vivace',        'Lively and fast, approximately 168–176 beats per minute. Bright and energetic in character.',                                                 'Tempo', 'Italian', NULL),
('Vivacissimo',   'Very fast and highly animated — an especially intense, energetic pace.',                                                                      'Tempo', 'Italian', NULL),
('Presto',        'Very fast, approximately 168–200 beats per minute.',                                                                                          'Tempo', 'Italian', NULL),
('Prestissimo',   'Extremely fast — as fast as possible, typically above 200 beats per minute.',                                                                 'Tempo', 'Italian', NULL),
('Accelerando',   'Gradually becoming faster. Abbreviated accel.',                                                                                               'Tempo', 'Italian', NULL),
('Ritardando',    'Gradually slowing down. Abbreviated rit. or ritard.',                                                                                         'Tempo', 'Italian', NULL),
('Rallentando',   'Gradually slowing down over a passage. Abbreviated rall.',                                                                                    'Tempo', 'Italian', NULL),
('Ritenuto',      'Held back — an immediate slowing of the tempo rather than a gradual reduction in speed. Abbreviated riten.',                                  'Tempo', 'Italian', NULL),
('Rubato',        'Flexible tempo — the performer takes rhythmic freedom, pushing and pulling the speed expressively for musical effect.',                        'Tempo', 'Italian', NULL),
('A tempo',       'Return to the original speed of the piece after a passage where the tempo has changed.',                                                      'Tempo', 'Italian', NULL),
('Tempo giusto',  'In exact, strict time — no flexibility or rhythmic freedom.',                                                                                 'Tempo', 'Italian', NULL),
('Meno mosso',    'Less motion — at a slower speed than the preceding passage.',                                                                                 'Tempo', 'Italian', NULL),
('Più mosso',     'More motion — at a faster speed than the preceding passage.',                                                                                 'Tempo', 'Italian', NULL),
('Poco a poco',   'Little by little — indicates a change that happens gradually, e.g. getting louder little by little.',                                         'Tempo', 'Italian', NULL),
('Subito',        'Suddenly — indicates an immediate change, e.g. suddenly becoming quiet.',                                                                     'Tempo', 'Italian', NULL),

