('Fortississimo', 'Extremely loud. Abbreviated fff.',                                                                                                            'Dynamics', 'Italian', '<em style="font-family:serif;font-style:italic;font-weight:700;font-size:1.1em">fff</em>'),
('Sforzando',     'A sudden, strong accent on a single note or chord. Abbreviated sfz or sf.',                                                                   'Dynamics', 'Italian', '<em style="font-family:serif;font-style:italic;font-weight:700;font-size:1.1em">sfz</em>'),
('Forte-piano',   'Loud immediately followed by soft — an abrupt dynamic contrast on a single note or chord. Abbreviated fp.',                                   'Dynamics', 'Italian', '<em style="font-family:serif;font-style:italic;font-weight:700;font-size:1.1em">fp</em>'),
