 '<svg width="36" height="20" viewBox="0 0 36 20" style="vertical-align:middle"><line x1="2" y1="3" x2="34" y2="10" stroke="currentColor" stroke-width="1.5" fill="none"/><line x1="2" y1="17" x2="34" y2="10" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Niente',        'Nothing — used to indicate fading to complete silence. Often written as "al niente" (to nothing) at the end of a passage getting softer.',    'Dynamics', 'Italian', '<em style="font-family:serif;font-style:italic;font-weight:700;font-size:1.1em">n</em>'),

-- ── ARTICULATION ─────────────────────────────────────────────────────────────
('Legato',        'Smooth and connected — notes flow into each other without any gap. Indicated by a curved line drawn over or under a group of notes.',
 'Articulation', 'Italian',
 '<svg width="38" height="14" viewBox="0 0 38 14" style="vertical-align:middle"><circle cx="6" cy="8" r="3.5" fill="currentColor"/><circle cx="19" cy="8" r="3.5" fill="currentColor"/><circle cx="32" cy="8" r="3.5" fill="currentColor"/><path d="M3,5 Q19,0 35,5" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Staccato',      'Short and detached — each note is clipped shorter than its written value, creating a small silence before the next note. Shown by a dot above or below the note head.',
 'Articulation', 'Italian',
 '<svg width="28" height="20" viewBox="0 0 28 20" style="vertical-align:middle"><circle cx="8" cy="14" r="3.5" fill="currentColor"/><circle cx="8" cy="4" r="2.5" fill="currentColor"/><circle cx="20" cy="14" r="3.5" fill="currentColor"/><circle cx="20" cy="4" r="2.5" fill="currentColor"/></svg>'),
('Tenuto',        'Hold the note for its full written duration, sometimes with a slight emphasis. Shown by a short horizontal line above or below the note.',
 'Articulation', 'Italian',
 '<svg width="28" height="20" viewBox="0 0 28 20" style="vertical-align:middle"><circle cx="8" cy="14" r="3.5" fill="currentColor"/><line x1="3" y1="5" x2="13" y2="5" stroke="currentColor" stroke-width="2"/><circle cx="20" cy="14" r="3.5" fill="currentColor"/><line x1="15" y1="5" x2="25" y2="5" stroke="currentColor" stroke-width="2"/></svg>'),
('Accent',        'Emphasise a note — play it with more weight or volume than the surrounding notes. Shown by a > symbol above or below the note.',
 'Articulation', 'Italian',
 '<svg width="20" height="16" viewBox="0 0 20 16" style="vertical-align:middle"><line x1="2" y1="8" x2="18" y2="2" stroke="currentColor" stroke-width="1.5"/><line x1="2" y1="8" x2="18" y2="14" stroke="currentColor" stroke-width="1.5"/></svg>'),
('Marcato',       'Strongly marked — played with considerable emphasis and weight. Shown by a ^ symbol above the note.',
 'Articulation', 'Italian',
 '<svg width="18" height="14" viewBox="0 0 18 14" style="vertical-align:middle"><line x1="2" y1="13" x2="9" y2="2" stroke="currentColor" stroke-width="1.5"/><line x1="9" y1="2" x2="16" y2="13" stroke="currentColor" stroke-width="1.5"/></svg>'),
('Portato',       'Semi-detached — notes are gently separated but not as abruptly clipped as a fully detached touch. Shown by a curved line with dots beneath each note.',
 'Articulation', 'Italian',
 '<svg width="38" height="18" viewBox="0 0 38 18" style="vertical-align:middle"><circle cx="6" cy="10" r="3.5" fill="currentColor"/><circle cx="19" cy="10" r="3.5" fill="currentColor"/><circle cx="32" cy="10" r="3.5" fill="currentColor"/><path d="M3,7 Q19,2 35,7" stroke="currentColor" stroke-width="1.5" fill="none"/><circle cx="6" cy="16" r="2" fill="currentColor"/><circle cx="19" cy="16" r="2" fill="currentColor"/><circle cx="32" cy="16" r="2" fill="currentColor"/></svg>'),
('Staccatissimo', 'Very short and sharply detached — notes are clipped to the briefest possible duration. Shown by a small wedge above or below the note.',
 'Articulation', 'Italian',
 '<svg width="28" height="22" viewBox="0 0 28 22" style="vertical-align:middle"><circle cx="8" cy="16" r="3.5" fill="currentColor"/><polygon points="8,2 5,8 11,8" fill="currentColor"/><circle cx="20" cy="16" r="3.5" fill="currentColor"/><polygon points="20,2 17,8 23,8" fill="currentColor"/></svg>'),
('Slur',          'A curved line connecting two or more notes of different pitches, indicating they should be played smoothly and without separation.',
 'Articulation', NULL,
 '<svg width="40" height="16" viewBox="0 0 40 16" style="vertical-align:middle"><circle cx="5" cy="11" r="3.5" fill="currentColor"/><circle cx="20" cy="11" r="3.5" fill="currentColor"/><circle cx="35" cy="11" r="3.5" fill="currentColor"/><path d="M3,8 Q20,0 37,8" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Tie',           'A curved line connecting two notes of the same pitch, combining their durations into one sustained sound.',
 'Articulation', NULL,
 '<svg width="36" height="14" viewBox="0 0 36 14" style="vertical-align:middle"><circle cx="5" cy="9" r="3.5" fill="currentColor"/><circle cx="31" cy="9" r="3.5" fill="currentColor"/><path d="M5,7 Q18,0 31,7" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Fermata',       'Hold the note (or rest) longer than its written value — the exact length is left to the performer or conductor. Also called a pause.',
 'Articulation', 'Italian', '<span style="font-size:1.6em">𝄐</span>'),

