('Trill',         'Rapid alternation between the written note and the note one step above it. Abbreviated tr, often followed by a wavy line.',
 'Ornaments', NULL,
 '<span style="font-family:serif;font-style:italic;font-weight:bold;font-size:1.05em">tr</span><svg width="28" height="12" viewBox="0 0 28 12" style="vertical-align:middle"><path d="M0,6 Q3.5,0 7,6 Q10.5,12 14,6 Q17.5,0 21,6 Q24.5,12 28,6" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Mordent',       'A quick alternation between the written note and the note one step below it, returning immediately to the written note. Shown by a wavy line with a vertical stroke through it.',
 'Ornaments', NULL,
 '<svg width="28" height="16" viewBox="0 0 28 16" style="vertical-align:middle"><path d="M2,8 Q6,2 10,8 Q14,14 18,8 Q22,2 26,8" stroke="currentColor" stroke-width="1.5" fill="none"/><line x1="10" y1="1" x2="10" y2="15" stroke="currentColor" stroke-width="1.5"/></svg>'),
('Inverted Mordent', 'A quick alternation between the written note and the note one step above it, returning immediately to the written note. Also called an upper mordent or pralltriller.',
 'Ornaments', NULL,
 '<svg width="28" height="16" viewBox="0 0 28 16" style="vertical-align:middle"><path d="M2,8 Q6,2 10,8 Q14,14 18,8 Q22,2 26,8" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>'),
('Turn',          'A four-note ornament that moves from the note above the written pitch, down through it to the note below, then back up to the written pitch.',
