-- ── FORM ─────────────────────────────────────────────────────────────────────
-- Form terms have no dedicated symbols except Coda
('Binary form',     'A two-part musical structure (A–B), where each section may be repeated.',                                                                   'Form', NULL, NULL),
('Ternary form',    'A three-part musical structure (A–B–A) — an opening section is followed by a contrasting middle section, after which the opening section returns.',  'Form', NULL, NULL),
('Rondo form',      'A structure in which a main theme returns repeatedly between contrasting sections: A–B–A–C–A or similar. The returning theme acts as a refrain.',  'Form', NULL, NULL),
('Sonata form',     'A large-scale structure with three main sections: an Exposition (where themes are introduced), a Development (where themes are explored and transformed), and a Recapitulation (where themes return).',  'Form', NULL, NULL),
('Theme and variations', 'A theme is stated and then repeated multiple times, each time with changes — in melody, rhythm, harmony, texture, or character.',       'Form', NULL, NULL),
('Canon',           'A technique where a melody is introduced by one voice and then imitated exactly by one or more other voices, each entering a short time later — creating overlapping layers of the same tune.',  'Form', NULL, NULL),
('Fugue',           'A composition built on a short theme (the subject) that is stated alone, then imitated in overlapping entries by additional voices, all woven together throughout the piece.',  'Form', NULL, NULL),
('Through-composed', 'A piece in which new music is written for each section throughout — no large sections repeat.',                                             'Form', NULL, NULL),
('Coda',            'A concluding passage that brings a piece or section to a close.',                                                                            'Form', 'Italian', '<span style="font-size:1.4em">𝄌</span>'),
('Exposition',      'The opening section of a movement where the main musical themes are first introduced and established.',                                      'Form', NULL, NULL),
('Development',     'A section where earlier musical ideas are fragmented, varied and taken through different moods and keys — creating tension and exploration.', 'Form', NULL, NULL),
('Recapitulation',  'A section where the main themes of a movement return, typically bringing a sense of resolution and homecoming.',                             'Form', NULL, NULL),
('Prelude',         'An introductory piece, or a short self-contained character piece.',                                                                          'Form', NULL, NULL),
('Nocturne',        'A lyrical, contemplative character piece, typically written for piano. Evokes the mood of the night.',                                       'Form', NULL, NULL),
('Étude',           'A study piece designed to develop a specific technical skill. The word is French for "study".',                                              'Form', 'French', NULL),
('Intermezzo',      'A short character piece, or a movement that falls between larger sections of a work.',                                                       'Form', 'Italian', NULL),
('Impromptu',       'A character piece that gives the impression of spontaneous improvisation.',                                                                  'Form', NULL, NULL),
('Ballade',         'A dramatic narrative piece, typically written as a large-scale single movement.',                                                            'Form', NULL, NULL),
('Scherzo',         'A lively, playful movement or piece, usually in triple time. Literally "joke" in Italian.',                                                  'Form', 'Italian', NULL),
('Minuet',          'An elegant triple-time dance at a moderate pace, common in Baroque and Classical era compositions.',                                         'Form', NULL, NULL),
('Suite',           'A collection of contrasting movements, often based on dances, grouped together as a single work.',                                           'Form', NULL, NULL),
('Concerto',        'A work for one or more solo instruments accompanied by an orchestra, typically in three movements.',                                         'Form', 'Italian', NULL),
('Sonata',          'A multi-movement work for one or two instruments. The term also refers to the structural conventions commonly used within such works.',       'Form', 'Italian', NULL),

-- ── RHYTHM ───────────────────────────────────────────────────────────────────
('Time signature',  'Two numbers stacked at the start of a piece: the top number indicates how many beats are in each bar; the bottom number indicates what kind of note equals one beat.',
 'Rhythm', NULL,
 '<span style="display:inline-flex;flex-direction:column;align-items:center;line-height:1.1;font-weight:bold;font-size:1.2em;font-family:serif;gap:0"><span>4</span><span>4</span></span>'),
('Common time',     'Four beats per bar, where each beat is a quarter note. One of the most frequently used time signatures. Often notated with a C symbol.',
 'Rhythm', NULL, '<span style="font-size:1.5em">𝄴</span>'),
('Cut time',        'Two beats per bar, where each beat is a half note. Music in cut time moves at a broader, two-in-a-bar pulse. Also called alla breve.',
 'Rhythm', NULL, '<span style="font-size:1.5em">𝄵</span>'),
('Syncopation',     'Emphasis placed on a beat that is normally weak, or between beats — creates a sense of rhythmic surprise or groove.',                         'Rhythm', NULL, NULL),
('Triplet',         'Three notes played evenly in the time normally occupied by two, indicated by a bracket and the number 3.',
 'Rhythm', NULL,
 '<svg width="38" height="20" viewBox="0 0 38 20" style="vertical-align:middle"><circle cx="6" cy="15" r="3.5" fill="currentColor"/><circle cx="19" cy="15" r="3.5" fill="currentColor"/><circle cx="32" cy="15" r="3.5" fill="currentColor"/><line x1="6" y1="11" x2="6" y2="6" stroke="currentColor" stroke-width="1.2"/><line x1="6" y1="6" x2="32" y2="6" stroke="currentColor" stroke-width="1.2"/><line x1="32" y1="6" x2="32" y2="11" stroke="currentColor" stroke-width="1.2"/><text x="19" y="5" text-anchor="middle" font-size="9" fill="currentColor" font-family="serif">3</text></svg>'),
('Duplet',          'Two notes played evenly across the time normally occupied by three, indicated by a bracket and the number 2.',
 'Rhythm', NULL,
 '<svg width="28" height="20" viewBox="0 0 28 20" style="vertical-align:middle"><circle cx="7" cy="15" r="3.5" fill="currentColor"/><circle cx="21" cy="15" r="3.5" fill="currentColor"/><line x1="7" y1="11" x2="7" y2="6" stroke="currentColor" stroke-width="1.2"/><line x1="7" y1="6" x2="21" y2="6" stroke="currentColor" stroke-width="1.2"/><line x1="21" y1="6" x2="21" y2="11" stroke="currentColor" stroke-width="1.2"/><text x="14" y="5" text-anchor="middle" font-size="9" fill="currentColor" font-family="serif">2</text></svg>'),
('Hemiola',         'A rhythmic device where the music shifts between a feeling of two groups of three beats and three groups of two beats — creating a sense of rhythmic ambiguity.',  'Rhythm', NULL, NULL),
('Anacrusis',       'One or more notes before the first full bar of a piece — also called an upbeat or pick-up.',                                                 'Rhythm', NULL, NULL),
('Downbeat',        'The first beat of a bar — typically the strongest, most emphasised beat.',                                                                   'Rhythm', NULL, NULL),
('Upbeat',          'A relatively weak beat that leads into a stronger beat, or the final beat of a bar that propels into the next bar.',                         'Rhythm', NULL, NULL),
('Polyrhythm',      'Two or more contrasting rhythmic patterns played simultaneously, e.g. three notes against two.',                                             'Rhythm', NULL, NULL),
('Augmentation',    'A compositional device where a musical theme is repeated with all its note values lengthened — typically doubled in duration.',              'Rhythm', NULL, NULL),
('Diminution',      'A compositional device where a musical theme is repeated with all its note values shortened — typically halved in duration.',                'Rhythm', NULL, NULL),
('Ostinato',        'A short rhythmic or melodic pattern repeated persistently throughout a section or entire piece.',                                             'Rhythm', 'Italian', NULL),
('Compound time',   'A time signature where each beat naturally divides into three equal parts. Examples include 6/8, 9/8 and 12/8.',
 'Rhythm', NULL,
 '<span style="display:inline-flex;flex-direction:column;align-items:center;line-height:1.1;font-weight:bold;font-size:1.2em;font-family:serif;gap:0"><span>6</span><span>8</span></span>'),
('Simple time',     'A time signature where each beat naturally divides into two equal parts. Examples include 2/4, 3/4 and 4/4.',
 'Rhythm', NULL,
 '<span style="display:inline-flex;flex-direction:column;align-items:center;line-height:1.1;font-weight:bold;font-size:1.2em;font-family:serif;gap:0"><span>4</span><span>4</span></span>'),

-- ── PITCH ────────────────────────────────────────────────────────────────────
('Sharp',           'Raises a note by one half-step (the smallest pitch distance in standard Western music). Shown by the ♯ symbol.',                            'Pitch', NULL, '<span style="font-size:1.4em">♯</span>'),
('Flat',            'Lowers a note by one half-step (the smallest pitch distance in standard Western music). Shown by the ♭ symbol.',                            'Pitch', NULL, '<span style="font-size:1.4em">♭</span>'),
('Natural',         'Cancels a previous sharp or flat, returning the note to its unaltered pitch. Shown by the ♮ symbol.',                                       'Pitch', NULL, '<span style="font-size:1.4em">♮</span>'),
('Double sharp',    'Raises a note by two half-steps (a whole step). Shown by the 𝄪 symbol.',                                                                   'Pitch', NULL, '<span style="font-size:1.4em">𝄪</span>'),
('Double flat',     'Lowers a note by two half-steps (a whole step). Shown by the 𝄫 symbol.',                                                                   'Pitch', NULL, '<span style="font-size:1.4em">𝄫</span>'),
('Semitone',        'The smallest distance between two pitches in standard Western music — equivalent to moving one key to the next on a piano, whether white or black. Also called a half step.', 'Pitch', NULL, NULL),
('Tone',            'A pitch distance of two half-steps — also called a whole step or whole tone. The distance from C to D, for example.',                       'Pitch', NULL, NULL),
('Octave',          'A pitch interval where the higher note vibrates at exactly double the frequency of the lower. Both notes share the same letter name, e.g. C to the next C.',  'Pitch', NULL, NULL),
('Enharmonic',      'Two notes that sound identical but are written differently, e.g. C♯ and D♭ are the same key on the piano but named differently depending on the key.',       'Pitch', NULL, NULL),
('Accidental',      'A sharp, flat, or natural sign placed before a note to temporarily alter its pitch within a bar, outside of what the key signature already specifies.',       'Pitch', NULL, '<span style="font-size:1.2em">♯ ♭ ♮</span>'),
('Ledger lines',    'Short lines added above or below the five-line staff to notate pitches that fall outside its range.',
 'Pitch', NULL,
 '<svg width="36" height="28" viewBox="0 0 36 28" style="vertical-align:middle"><line x1="2" y1="8" x2="34" y2="8" stroke="currentColor" stroke-width="1"/><line x1="2" y1="14" x2="34" y2="14" stroke="currentColor" stroke-width="1"/><line x1="2" y1="20" x2="34" y2="20" stroke="currentColor" stroke-width="1"/><line x1="10" y1="26" x2="26" y2="26" stroke="currentColor" stroke-width="1.5"/><ellipse cx="18" cy="26" rx="7" ry="4.5" fill="currentColor" transform="rotate(-15,18,26)"/></svg>'),
('Ottava',          'Play one octave higher than written. Shown as 8va above the passage, ending with a dotted line.',                                           'Pitch', 'Italian', '<em style="font-style:italic;font-size:1.0em">8va ·····</em>'),
('Ottava bassa',    'Play one octave lower than written. Shown as 8vb or 8ba below the passage.',                                                                'Pitch', 'Italian', '<em style="font-style:italic;font-size:1.0em">8vb ·····</em>'),
('Loco',            'Return to playing at the written pitch after a passage that was played at a different octave.',                                              'Pitch', 'Italian', NULL),
('Register',        'The range of pitches in a particular part of an instrument or voice — for example, the low, middle or upper range.',                         'Pitch', NULL, NULL),

-- ── HARMONY ──────────────────────────────────────────────────────────────────
-- Harmony concepts are described in text in scores — no dedicated standalone symbols
('Major scale',     'An ordered sequence of eight notes with a bright, settled character. Built using the interval pattern: whole, whole, half, whole, whole, whole, half step.',  'Harmony', NULL, NULL),
('Minor scale',     'An ordered sequence of eight notes with a darker, more serious character. The natural minor uses the pattern: whole, half, whole, whole, half, whole, whole step.',  'Harmony', NULL, NULL),
('Chromatic scale', 'A scale made entirely of half-steps — twelve pitches spanning one octave, using every adjacent note.',                                      'Harmony', NULL, NULL),
('Pentatonic scale','A scale of five notes per octave. The major pentatonic version has a bright, open sound and is common in folk and popular music worldwide.', 'Harmony', NULL, NULL),
('Whole tone scale','A scale built entirely of whole steps — six notes per octave. Creates a dreamy, ambiguous sound with no strong sense of a home note.',       'Harmony', NULL, NULL),
('Interval',        'The distance in pitch between two notes, measured and named according to how many steps apart they are, e.g. a third, a fifth, an octave.', 'Harmony', NULL, NULL),
('Triad',           'A three-note chord built by stacking two intervals of a third: a root note, a note a third above it, and a note a fifth above the root.',   'Harmony', NULL, NULL),
('Seventh chord',   'A four-note chord formed by adding a note a seventh above the root to a basic three-note chord.',                                           'Harmony', NULL, NULL),
('Tonic',           'The first note of a scale — the home note and key centre of a piece. Music built around the tonic tends to feel settled and resolved.',     'Harmony', NULL, NULL),
('Dominant',        'The fifth note of a scale. Chords built on this note create tension that typically pulls toward the home note of the key.',                  'Harmony', NULL, NULL),
('Subdominant',     'The fourth note of a scale. Chords built on this note create a sense of departure or openness away from the home key.',                     'Harmony', NULL, NULL),
('Leading note',    'The seventh note of a scale — one half-step below the home note of the key. Creates a strong upward pull toward resolution.',               'Harmony', NULL, NULL),
('Modulation',      'Moving from one key to another within a piece of music.',                                                                                   'Harmony', NULL, NULL),
('Transposition',   'Moving a melody or passage to a different pitch level, keeping all the intervals exactly the same.',                                         'Harmony', NULL, NULL),
('Perfect cadence', 'A chord progression that moves from the chord built on the fifth note of the scale to the chord built on the home note — creates a strong sense of finality, like a musical full stop.',  'Harmony', NULL, NULL),
('Plagal cadence',  'A chord progression that moves from the chord built on the fourth note of the scale to the chord built on the home note. Known as the "Amen" cadence, common in hymns.',  'Harmony', NULL, NULL),
('Imperfect cadence', 'A cadence that ends on the chord built on the fifth note of the scale — feels unresolved, like a musical question.',                      'Harmony', NULL, NULL),
('Interrupted cadence', 'A cadence where the music appears to be heading toward the home chord but unexpectedly lands on a different chord instead — creates surprise.',  'Harmony', NULL, NULL),
('Diatonic',        'Using only the notes that belong to the current key, without any additions.',                                                                'Harmony', NULL, NULL),
('Chromatic',       'Using notes from outside the current key — adding colour, tension or a heightened sense of expression.',                                     'Harmony', NULL, NULL),
('Consonance',      'A combination of notes that sounds stable and pleasing — creates a sense of rest.',                                                          'Harmony', NULL, NULL),
('Dissonance',      'A combination of notes that sounds tense or unstable — typically wants to move toward a more settled sound.',                                'Harmony', NULL, NULL),
('Counterpoint',    'Two or more independent melodic lines played at the same time, each with its own rhythm and contour, yet fitting together harmonically.',    'Harmony', NULL, NULL),
('Pedal point',     'A sustained or repeated note — usually in the bass — held while the harmonies above it change.',                                            'Harmony', NULL, NULL),
('Inversion',       'When a chord is arranged so that a note other than the bottom (root) note is in the bass. First inversion has the third in the bass; second inversion has the fifth.',  'Harmony', NULL, NULL),
('Chord',           'Three or more notes sounded at the same time.',                                                                                             'Harmony', NULL, NULL),
('Dorian mode',     'A scale with a minor character but with a raised sixth degree — giving it a slightly brighter feel than a standard minor scale. Common in folk and jazz music.',  'Harmony', NULL, NULL),
('Phrygian mode',   'A scale with a minor character, distinguished by a lowered second degree — the second note of the scale is only a half-step above the first. Common in flamenco music.',  'Harmony', NULL, NULL),
('Lydian mode',     'A scale with a major character, distinguished by a raised fourth degree — the fourth note is a half-step higher than in a standard major scale. Has a bright, floating quality.',  'Harmony', NULL, NULL),
('Mixolydian mode', 'A scale with a major character but with a lowered seventh degree. Common in folk, rock and blues music.',                                   'Harmony', NULL, NULL),
('Aeolian mode',    'A natural minor scale — six notes up from the starting note of a major scale, using the same set of notes.',                                'Harmony', NULL, NULL),
('Locrian mode',    'A scale with a dark, unstable character, rarely used in practice. Its fifth note is lowered, removing the usual feeling of stability.',     'Harmony', NULL, NULL),

